import json
from pathlib import Path

doc = json.loads(Path("ai-log/session.json").read_text(encoding="utf-8"))
msgs = doc["messages"]

def part_preview(p):
    if not isinstance(p, dict):
        return ("?str", None)
    t = p.get("type")
    if t == "text":
        return ("text", len(p.get("text", "") or ""))
    if t == "tool":
        state = p.get("state", {})
        inp = state.get("input")
        out = state.get("output")
        return ("tool", (len(str(inp)) if inp is not None else 0, len(str(out)) if out is not None else 0))
    return (t, None)

for idx in range(len(msgs)):
    it = msgs[idx]
    if it.get("info", {}).get("role") != "user":
        continue
    parts = it.get("parts", [])
    desc = [part_preview(p) for p in parts]
    total = sum((x[1] if isinstance(x[1], int) else 0) for x in desc)
    print(f"idx={idx} parts={len(parts)} desc={desc} sum_text_chars={total}")
