            t = p["text"]
            if redacted.match(t):
                red += 1
            else:
                real += 1

print(f"partes de texto 'text': reais={real}, redigidas={red}")

# confirmar se todas as partes user são redigidas e assistant também
from collections import Counter
cnt = Counter()
for it in msgs:
    role = it.get("info", {}).get("role")
    for p in it.get("parts", []) if isinstance(it.get("parts"), list) else []:
        if isinstance(p, dict) and p.get("type")=="text":
            t = p.get("text","")
            key = f"{role}:redacted" if redacted.match(t) else f"{role}:real"
            cnt[key]+=1
print("distribuição:", dict(cnt))
# amostra de um texto 'real' se houver
for it in msgs:
    for p in it.get("parts", []) if isinstance(it.get("parts"), list) else []:
        if isinstance(p, dict) and p.get("type")=="text" and not redacted.match(p.get("text","")) and len(p.get("text",""))>0:
